fn solve(n: i8, s: Vec<char>) -> i8 {
    // If there's only one character or less, there are no adjacent pairs.
    if n < 2 {
        return 0;
    }

    let mut count: i8 = 0;
    // Convert n to usize for indexing
    let len = n as usize;
    for i in 0..(len - 1) {
        if s[i] == s[i + 1] {
            count += 1;
        }
    }

    count
}

